parameters.jsCode:
const inputItems = $input.all();
const outputItems = [];

for (const item of inputItems) {
  const files = item.binary || {};

  for (const [fieldName, file] of Object.entries(files)) {
    outputItems.push({
      json: {
        source_field: fieldName,
        file_name: file.fileName || fieldName,
        mime_type: file.mimeType || "unknown"
      },
      binary: {
        data: file
      }
    });
  }
}

if (outputItems.length === 0) {
  throw new Error("No files uploaded. Please upload at least one document.");
}

return outputItems;

const extractedItems = $input.all();
const sourceItems = $("Normalize Uploaded Files").all();

const documents = [];

for (let i = 0; i < extractedItems.length; i++) {
  const content = extractedItems[i].json.content;
  const source = sourceItems[i]?.json || {};

  if (typeof content !== "string" || !content.trim()) {
    continue;
  }

  documents.push({
    source_id: `DOC-${String(documents.length + 1).padStart(3, "0")}`,
    file_name: source.file_name || `Document_${i + 1}.txt`,
    source_type: source.source_field || "Supporting Document",
    content: content.trim()
  });
}

if (documents.length === 0) {
  throw new Error("No readable document content found.");
}

const combinedText = documents.map(doc =>
  `=== SOURCE ${doc.source_id}: ${doc.file_name} ===\n` +
  `Source Type: ${doc.source_type}\n\n` +
  doc.content
).join("\n\n--- END OF DOCUMENT ---\n\n");

return [{
  json: {
    document_count: documents.length,
    documents: documents,
    transcript: combinedText
  }
}];

const extracted = $input.first().json.output;
const documents = $("Combine Documents").first().json.documents;

const errors = [];
const warnings = [];
const validStatuses = new Set([
  "confirmed",
  "disputed",
  "proposed"
]);

const sourceMap = new Map(
  documents.map(doc => [doc.source_id, doc])
);

const normalize = text =>
  String(text || "").replace(/\s+/g, " ").trim();

const requirements = [
  ...(extracted.functional_requirements || []),
  ...(extracted.non_functional_requirements || [])
];

const seenIds = new Set();
let evidenceChecked = 0;

for (const req of requirements) {

const idMatch = /^(FR|NFR)-(\d{1,3})$/.exec(req.id || "");

if (!idMatch) {
  errors.push(`Invalid requirement ID: ${req.id}`);
} else {
  req.id = `${idMatch[1]}-${idMatch[2].padStart(2, "0")}`;
}


  if (seenIds.has(req.id)) {
    errors.push(`Duplicate requirement ID: ${req.id}`);
  }
  seenIds.add(req.id);

  if (!validStatuses.has(req.status)) {
    errors.push(`${req.id}: Invalid status '${req.status}'`);
  }

  if (!Array.isArray(req.sources) || req.sources.length === 0) {
    errors.push(`${req.id}: No source evidence provided`);
    continue;
  }

  for (const source of req.sources) {
    const original = sourceMap.get(source.source_id);

    if (!original) {
      errors.push(`${req.id}: Unknown source ${source.source_id}`);
      continue;
    }

    if (source.file_name !== original.file_name) {
      errors.push(`${req.id}: Filename does not match source ID`);
    }

    const evidence = normalize(source.evidence);
    const originalText = normalize(original.content);

if (!evidence || !originalText.includes(evidence)) {
  errors.push(
    `${req.id}: Evidence not found in ${source.source_id}. ` +
    `AI quotation: "${source.evidence}"`
  );
} else {
      evidenceChecked++;
    }
  }
}

if (requirements.length === 0) {
  warnings.push("No requirements extracted.");
}

if (extracted.insufficient_information === true) {
  warnings.push("Extractor marked input as insufficient.");
}

const validationPassed = errors.length === 0;

return [{
  json: {
    output: extracted,
    validation: {
      passed: validationPassed,
      total_requirements: requirements.length,
      evidence_verified: evidenceChecked,
      error_count: errors.length,
      warning_count: warnings.length,
      errors,
      warnings
    }
  }
}];

const input = $input.first().json;
const extracted = JSON.parse(JSON.stringify(input.output));

const documents = $("Combine Documents").first().json.documents;

const sourceMap = new Map(
  documents.map(doc => [doc.source_id, doc])
);

const repairs = [];
const unresolved = [];

const normalize = text =>
  String(text || "").replace(/\s+/g, " ").trim();

const requirements = [
  ...(extracted.functional_requirements || []),
  ...(extracted.non_functional_requirements || [])
];

for (const req of requirements) {
  for (const source of req.sources || []) {
    const original = sourceMap.get(source.source_id);

    if (!original) {
      unresolved.push(
        `${req.id}: Unknown source ${source.source_id}`
      );
      continue;
    }

    const originalText = normalize(original.content);
    const evidence = normalize(source.evidence);

    // Evidence already matches: no repair needed.
    if (evidence && originalText.includes(evidence)) {
      continue;
    }

    // Try to match a distinctive ending of the quotation.
    // Require at least 8 words to reduce accidental matches.
    const words = evidence.split(/\s+/).filter(Boolean);

    if (words.length < 8) {
      unresolved.push(
        `${req.id}: Evidence too short for safe repair`
      );
      continue;
    }

    const anchor = words.slice(-8).join(" ");
    const firstMatch = originalText.indexOf(anchor);

    if (firstMatch === -1) {
      unresolved.push(
        `${req.id}: No matching evidence anchor found`
      );
      continue;
    }

    // Reject ambiguous matches.
    const secondMatch = originalText.indexOf(
      anchor,
      firstMatch + anchor.length
    );

    if (secondMatch !== -1) {
      unresolved.push(
        `${req.id}: Multiple possible evidence matches`
      );
      continue;
    }

    // Locate the sentence or dialogue segment containing
    // the matching anchor.
    const sentenceStart = Math.max(
      originalText.lastIndexOf(". ", firstMatch - 1) + 2,
      originalText.lastIndexOf("? ", firstMatch - 1) + 2,
      originalText.lastIndexOf("! ", firstMatch - 1) + 2
    );

    const ending = originalText.slice(firstMatch);
    const sentenceEndMatch = ending.match(/[.!?](?:\s|$)/);

    const sentenceEnd = sentenceEndMatch
      ? firstMatch + sentenceEndMatch.index + 1
      : Math.min(originalText.length, firstMatch + 200);

    const candidate = originalText
      .slice(sentenceStart, sentenceEnd)
      .trim();

    // Only accept a repair if the anchor remains present.
    if (candidate && candidate.includes(anchor)) {
      const previousEvidence = source.evidence;
      source.evidence = candidate;

      repairs.push({
        requirement_id: req.id,
        source_id: source.source_id,
        old_evidence: previousEvidence,
        new_evidence: candidate
      });
    } else {
      unresolved.push(
        `${req.id}: Unable to construct matching quotation`
      );
    }
  }
}

return [{
  json: {
    output: extracted,
    repair: {
      attempted: true,
      repaired_count: repairs.length,
      unresolved_count: unresolved.length,
      repairs,
      unresolved
    }
  }
}];

