const prd = $input.first().json.text || "";

const extracted = $("Requirement Extractor")
  .first().json.output;

const errors = [];
const warnings = [];

const requiredSections = [
  "Product Overview",
  "Goals and Objectives",
  "User Personas",
  "Feature Requirements",
  "Acceptance Criteria",
  "Out of Scope",
  "Dependencies",
  "Assumptions",
  "Open Questions",
  "Timeline"
];

// Check the 10 required PRD sections.
for (const section of requiredSections) {
  const found = prd
    .toLowerCase()
    .includes(section.toLowerCase());

  if (!found) {
    errors.push(`Missing PRD section: ${section}`);
  }
}

// Collect requirement IDs from extracted JSON.
const requirements = [
  ...(extracted.functional_requirements || []),
  ...(extracted.non_functional_requirements || [])
];

const normalizeId = id => {
  const match = /^(FR|NFR)-(\d+)$/.exec(id || "");
  if (!match) return id;
  return `${match[1]}-${match[2].padStart(2, "0")}`;
};

const missingRequirements = [];

for (const req of requirements) {
  const id = normalizeId(req.id);

  const pattern = new RegExp(
    `\\b${id.replace("-", "\\-")}\\b`
  );

  if (!pattern.test(prd)) {
    missingRequirements.push(id);
  }
}

if (missingRequirements.length > 0) {
  errors.push(
    `Missing requirement IDs: ${missingRequirements.join(", ")}`
  );
}

const passed = errors.length === 0;

return [{
  json: {
    text: prd,
    prd_validation: {
      passed,
      required_sections: requiredSections.length,
      total_requirements: requirements.length,
      missing_requirements: missingRequirements,
      error_count: errors.length,
      warning_count: warnings.length,
      errors,
      warnings
    }
  }
}];

const prd = $("PRD Generator").first().json.text;
const stories = $("Story Breakdown").first().json.text;
const gaps = $("Gap Analyzer").first().json.text;

if (!prd || !stories || !gaps) {
  throw new Error(
    "One or more generated documents are missing."
  );
}

const featureName = $("Requirement Extractor")
  .first().json.output.feature_name || "PRD Genie";

const safeName = featureName
  .replace(/[^a-zA-Z0-9_-]+/g, "_")
  .replace(/^_+|_+$/g, "");

const timestamp = new Date()
  .toISOString()
  .replace(/[:.]/g, "-");

const files = [
  {
    type: "PRD",
    file_name: `${safeName}_PRD_${timestamp}.md`,
    content: prd
  },
  {
    type: "User Stories",
    file_name: `${safeName}_User_Stories_${timestamp}.md`,
    content: stories
  },
  {
    type: "Gap Analysis",
    file_name: `${safeName}_Gap_Analysis_${timestamp}.md`,
    content: gaps
  }
];

return files.map(file => ({
  json: {
    feature_name: featureName,
    document_type: file.type,
    file_name: file.file_name,
    content: file.content
  }
}));

