const files = $input.all();

const documents = files.map(item => {
  const file = item.json;

  return {
    name: file.name,
    file_id: file.id,
    view_url: file.webViewLink,
    download_url: file.webContentLink || null
  };
});

return [{
  json: {
    status: "completed",
    document_count: documents.length,
    documents
  }
}];
